21	    CHAOSPhysReg::CHAOSPhysReg(const CHAOSPhysRegParams &p)
22	        : SimObject(p),
23	          cpu(dynamic_cast<o3::CPU *>(p.cpu)),
24	          fi_mode(stringToMode(p.injectionMode)),
25	          target_phys_idx(p.targetPhysRegIdx),
26	          target_arch_idx(p.targetArchRegIdx),
27	          reg_target_class(stringToRegClassSel(p.regTargetClass)),
28	          probability(p.probability),
29	          num_bits_to_change(p.bitsToChange),
30	          fault_type_enum(stringToFaultType(p.faultType)),
31	          fault_mask(std::bitset<32>(p.faultMask)),
32	          bit_flip_prob(0.9),
33	          stuck_at_zero_prob(0.05),
34	          stuck_at_one_prob(0.05),
35	          first_clock(Cycles(p.firstClock)),
36	          last_clock(Cycles(p.lastClock)),
37	          max_faults(p.maxFaults),
38	          faults_injected_count(0),
39	          rng_seed(p.rngSeed),
40	          write_log(p.writeLog),
41	          attackEvent([this] { this->attackCheck(); }, name()),
42	          periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
43	          readTraceEvent([this] { this->readTraceCheck(); }, name() + ".readTrace"),
44	          stats(nullptr)
45	    {
46	        if (!cpu) {
47	            throw std::runtime_error(
48	                "CHAOSPhysReg: cpu is not an O3CPU. CHAOSPhysReg only supports "
49	                "O3CPU (it needs regFile/renameMap). Cast failed.");
50	        }
51	        if (probability > 0.0) {
52	            log_stream = simout.create("fault_injections.log", false, true);
53	            if (!log_stream || !log_stream->stream()) {
54	                panic("CHAOSPhysReg: Could not open log file");
55	            }
56	            stats = std::make_unique<CHAOSPhysRegStats>(this);
57	            rng.seed(rng_seed != 0 ? rng_seed : rd());
58	            if (num_bits_to_change == -1) {
59	                std::uniform_int_distribution<int> dist(1, 32);
60	                num_bits_to_change = dist(rng);
61	            }
62	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
63	            unsigned next_fault_cycle_distance = inter_fault_cycles_dist(rng);
64	            scheduleAttackEvent(first_clock + Cycles(next_fault_cycle_distance));
65	            scheduleCheckPermanentFault(first_clock + Cycles(1));
66	        }
67	    }
