143	    int
144	    CHAOSPhysReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
145	    {
146	        int mask = 0;
147	        std::uniform_int_distribution<int> bitDist(0, len - 1);
148	        while (bits_to_change-- > 0) mask |= (1 << bitDist(gen));
149	        return mask;
