152	    // Core: resolve a target PHYSICAL register id according to the fi_mode,
153	    // then read-modify-write it directly in the physical register file.
154	    // This is the key difference from CHAOSReg (which wrote the commitRenameMap
155	    // phys reg via ThreadContext::setReg — a backdoor that doesn't propagate
156	    // to in-flight instructions on O3).
157	    void
158	    CHAOSPhysReg::processFault(ThreadID tid)
159	    {
160	        // 1. Resolve target register class (integer / floating_point / vector).
161	        // 'both' picks one at random per injection across the three classes (a
162	        // real cell doesn't know its class either; this mirrors the ITC'23/GeFIN
163	        // phys abstraction).
164	        gem5::RegClassType target_class = gem5::IntRegClass;
165	        if (reg_target_class == RegClassSel::FloatingPoint) {
166	            target_class = gem5::FloatRegClass;
167	        } else if (reg_target_class == RegClassSel::Vector) {
168	            target_class = gem5::VecRegClass;
169	        } else if (reg_target_class == RegClassSel::Both) {
170	            switch (std::uniform_int_distribution<>(0, 2)(rng)) {
171	              case 0: target_class = gem5::IntRegClass; break;
172	              case 1: target_class = gem5::FloatRegClass; break;
173	              default: target_class = gem5::VecRegClass; break;
174	            }
175	        }
176	
177	        // 2. Resolve target physical register id.
178	        PhysRegIdPtr phys_reg = nullptr;
179	        int chosen_phys_idx = -1;     // for logging
180	        int chosen_arch_idx = -1;     // for logging (arch modes)
181	
182	        if (fi_mode == Mode::Phys) {
183	            // Inject by physical register index. A real defective cell has no
184	            // notion of architectural registers; whoever is allocated to this
185	            // slot gets hit. This is the ITC'23/GeFIN abstraction.
186	            int n;
187	            if (target_class == gem5::FloatRegClass)
188	                n = (int)cpu->physRegFile().numFloatPhysRegs();
189	            else if (target_class == gem5::VecRegClass)
190	                n = (int)cpu->physRegFile().numVecPhysRegs();
191	            else
192	                n = (int)cpu->physRegFile().numIntPhysRegs();
193	            if (n <= 0) return;
194	            chosen_phys_idx = (target_phys_idx >= 0)
195	                ? target_phys_idx
196	                : std::uniform_int_distribution<>(0, n - 1)(rng);
197	            if (chosen_phys_idx >= n) return;
198	            if (target_class == gem5::FloatRegClass)
199	                phys_reg = cpu->physRegFile().floatPhysRegId(chosen_phys_idx);
200	            else if (target_class == gem5::VecRegClass)
201	                phys_reg = cpu->physRegFile().vecPhysRegId(chosen_phys_idx);
202	            else
203	                phys_reg = cpu->physRegFile().intPhysRegId(chosen_phys_idx);
204	
205	            // Liveness probe: is this physical slot currently FREE (inactive)
206	            // or ALLOCATED (active)? Correct criterion per project notes: a phys
207	            // reg NOT in the free list is allocated — it may be held as a source
208	            // by in-flight renamed-but-unexecuted instructions even if no rename
209	            // map entry currently maps it (older version superseded but not yet
210	            // released). So "not free" = active = may be read. (The earlier
211	            // "rename map reverse-walk" criterion was too narrow and mislabeled
212	            // some live slots as dead, producing the dead-slot SDC anomaly.)
213	            bool is_free = cpu->physFreeList().isFree(target_class, phys_reg);
214	            free_list_size_at_inject = cpu->physFreeList().numFreeRegs(
215	                target_class);
216	            if (!is_free) {
217	                // active — also record which arch reg (if any) maps to it now,
218	                // for diagnostics (walk rename map; best-effort, not the
219	                // liveness source of truth).
220	                gem5::ThreadContext *tc = cpu->getContext(tid);
221	                if (tc) {
222	                    gem5::BaseISA *isa = tc->getIsaPtr();
223	                    if (isa) {
224	                        const auto &rc = isa->regClasses();
225	                        const gem5::RegClass *ic = rc[target_class];
226	                        int na = ic ? ic->numRegs() : 0;
227	                        // X0-X30 (cap 31) for int; V0-V31 (cap 32) for
228	                        // float AND vector (AArch64 V/D/Q share the file).
229	                        int cap;
230	                        if (target_class == gem5::IntRegClass)
231	                            cap = (na < 31 ? na : 31);
232	                        else
233	                            cap = (na < 32 ? na : 32);
234	                        for (int a = 0; a < cap; a++) {
235	                            gem5::RegId ar(*ic, a);
236	                            const gem5::RegId flat = ar.flatten(*isa);
237	                            PhysRegIdPtr pm =
238	                                cpu->frontRenameMap()[tid].lookup(flat);
239	                            if (pm && pm->index() == chosen_phys_idx) {
240	                                chosen_arch_idx = a;
241	                                break;
242	                            }
243	                        }
244	                    }
245	                }
246	            } else {
247	                chosen_arch_idx = -2;  // sentinel: free/inactive
248	            }
249	        } else {
250	            // arch_frontend: renameMap.lookup      (in-flight mapping)
251	            // arch_commit:   commitRenameMap.lookup (committed mapping = CHAOSReg)
252	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
253	            if (!thread_context) return;
254	            gem5::BaseISA *isa = thread_context->getIsaPtr();
255	            if (!isa) return;
256	            const auto &reg_classes = isa->regClasses();
257	            const gem5::RegClass *reg_class = reg_classes[target_class];
258	            if (!reg_class || reg_class->numRegs() == 0) return;
259	            int arch_idx = target_arch_idx;
260	            if (arch_idx < 0 || arch_idx >= reg_class->numRegs()) return;
261	            chosen_arch_idx = arch_idx;
262	            gem5::RegId arch_reg(*reg_class, arch_idx);
263	            // flatten to match the per-class rename map's indexing
264	            const gem5::RegId flat = arch_reg.flatten(*isa);
265	            if (fi_mode == Mode::ArchFrontend)
266	                phys_reg = cpu->frontRenameMap()[tid].lookup(flat);
267	            else // ArchCommit
268	                phys_reg = cpu->commitRenameMapAccess()[tid].lookup(flat);
269	            if (!phys_reg) return;
270	            chosen_phys_idx = phys_reg->index();
271	        }
272	
273	        if (!phys_reg) return;
274	
275	        // 3. Read current physical reg value, apply fault, write back.
276	        // VecRegClass holds a whole vector in a buffer (not a scalar RegVal),
277	        // so it goes through the getReg/setReg void*-overload; the fault mask
278	        // is applied to the first 8 bytes (one 64-bit word — enough to corrupt
279	        // the low lane of a NEON/SVE vector and propagate as SDC). int/float/
280	        // vecelem stay on the scalar RegVal path.
281	        FaultType chosen = fault_type_enum;
282	        if (fault_type_enum == FaultType::Random) {
283	            int idx = random_fault_distribution(rng);
284	            chosen = static_cast<FaultType>(idx);
285	        }
286	
287	        int mask = fault_mask.any()
288	            ? fault_mask.to_ulong()
289	            : generateRandomMask(rng, num_bits_to_change, 32);
290	
291	        if (target_class == gem5::VecRegClass) {
292	            // Buffer path: read the whole vector, corrupt the low word, write back.
293	            uint8_t buf[64];  // SVE max 2048b=256B; 64B head suffices for low-word FI
294	            memset(buf, 0, sizeof(buf));
295	            cpu->physRegFile().getReg(phys_reg, buf);
296	            uint64_t *word0 = reinterpret_cast<uint64_t*>(buf);
297	            switch (chosen) {
298	              case FaultType::StuckAtZero:
299	                *word0 &= ~(uint64_t)mask;
300	                stats->numStuckAtZero++;
301	                stats->numPermanentFaults++;
302	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
303	                break;
304	              case FaultType::StuckAtOne:
305	                *word0 |= (uint64_t)mask;
306	                stats->numStuckAtOne++;
307	                stats->numPermanentFaults++;
308	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
309	                break;
310	              case FaultType::BitFlip:
311	                *word0 ^= (uint64_t)mask;
312	                stats->numBitFlips++;
313	                break;
314	              default: break;
315	            }
316	            cpu->physRegFile().setReg(phys_reg, buf);
317	        } else {
318	            // Scalar path (int / float / vecelem).
319	            gem5::RegVal reg_val = cpu->physRegFile().getReg(phys_reg);
320	            switch (chosen) {
321	              case FaultType::StuckAtZero:
322	                reg_val &= ~mask;
323	                stats->numStuckAtZero++;
324	                stats->numPermanentFaults++;
325	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
326	                break;
327	              case FaultType::StuckAtOne:
328	                reg_val |= mask;
329	                stats->numStuckAtOne++;
330	                stats->numPermanentFaults++;
331	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
332	                break;
333	              case FaultType::BitFlip:
334	                reg_val ^= mask;
335	                stats->numBitFlips++;
336	                break;
337	              default: break;
338	            }
339	            cpu->physRegFile().setReg(phys_reg, reg_val);
340	        }
341	        stats->numFaultsInjected++;
342	        ++faults_injected_count;
343	
344	        // Start read-tracing this phys slot until workload end, to measure
345	        // whether the injected cell is actually read after injection.
346	        // (Closure check: SDC|read>0 should be similar for layer2 & layer3,
347	        //  SDC|read==0 should be ~0.) The readTraceEvent reschedules itself
348	        // every 1000 cycles until all threads halt, then writes the final
349	        // read count to the log.
350	        traced_phys_idx = chosen_phys_idx;
351	        reads_before_overwrite = 0;
352	        trace_overwritten = false;
353	        overwrite_recorded = false;
354	        overwritten_at_cycle = 0;
355	        cpu->physRegFile().setReadTraceTarget(target_class, chosen_phys_idx);
356	        if (!readTraceEvent.scheduled()) {
357	            schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
358	        }
359	
360	        if (write_log) {
361	            *(log_stream->stream())
362	                << "Cycle: " << cpu->curCycle()
363	                << ", CPU: " << cpu->name()
364	                << ", Thread: " << tid
365	                << ", Mode: " << (fi_mode == Mode::Phys ? "phys"
366	                              : fi_mode == Mode::ArchFrontend ? "arch_frontend"
367	                              : "arch_commit")
368	                << ", RegClass: " << (target_class == gem5::FloatRegClass
369	                                       ? "fp"
370	                                       : (target_class == gem5::VecRegClass
371	                                          ? "vec" : "int"))
372	                << ", PhysReg[" << chosen_phys_idx << "]"
373	                << (fi_mode == Mode::Phys
374	                    ? (chosen_arch_idx == -2
375	                       ? " (Inactive/free slot)"
376	                       : (chosen_arch_idx >= 0
377	                          ? " (Active, mapped from ArchReg[" + std::to_string(chosen_arch_idx) + "])"
378	                          : " (Active, held by in-flight inst, no current rename-map entry)"))
379	                    : (chosen_arch_idx >= 0
380	                       ? " (<= ArchReg[" + std::to_string(chosen_arch_idx) + "])"
381	                       : ""))
382	                << ", FaultType: " << faultTypeToString(chosen)
383	                << ", Mask: " << std::bitset<32>(mask)
384	                << ", FreeListSize: " << free_list_size_at_inject
385	                << std::endl;
386	        }
387	    }
