389	    void
390	    CHAOSPhysReg::attackCheck()
391	    {
392	        if (!probability) return;
393	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
394	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
395	            if (!thread_context || thread_context->status() == ThreadContext::Halted)
396	                continue;
397	            processFault(tid);
398	        }
399	        // maxFaults cap (mirrors CHAOSReg)
400	        if (max_faults != 0 && faults_injected_count >= max_faults) {
401	            unscheduleAttackEvent();
402	            return;
403	        }
404	        bool any_active = false;
405	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
406	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
407	            if (thread_context && thread_context->status() != ThreadContext::Halted) {
408	                any_active = true; break;
409	            }
410	        }
411	        if (any_active) {
412	            Cycles next = Cycles(inter_fault_cycles_dist(rng));
413	            if (last_clock == 0 || (next + cpu->curCycle()) <= last_clock)
414	                scheduleAttackEvent(next);
415	        } else {
416	            unscheduleAttackEvent();
417	        }
418	    }
